(()=>{
  'use strict';
  const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  function desktop(){return window.beastDesktop||{};}
  function workspace(){const s=window.BeastStore?.get?.()||{};return {root:s.workspace?.root||'',folderRoot:s.workspace?.root||'',language:s.editor?.language||'plaintext',target:s.executionTarget?.kind||'local'};}
  function mount(){const page=document.querySelector('.beast-settings-page');if(!page||page.querySelector('[data-profile-studio]'))return;const panel=document.createElement('section');panel.className='beast-card beast-profile-studio';panel.dataset.profileStudio='true';panel.innerHTML=`<div class="beast-panel-head"><div><span class="eyebrow">PROFILE COVENANT</span><h3>Scoped Settings & Project Profiles</h3></div><span class="status-chip">SCHEMA V2</span></div><div class="profile-scope-row"><label>Scope<select data-profile-scope><option value="user">User</option><option value="workspace">Workspace</option><option value="folder">Folder</option><option value="language">Language</option><option value="target">Target</option></select></label><label>Language<input data-profile-language value="plaintext"></label><label>Target<input data-profile-target value="local"></label></div><textarea data-profile-json spellcheck="false" aria-label="Scoped settings JSON">{}</textarea><div class="profile-actions"><button class="beast-button secondary" data-profile-action="load">Load Scope</button><button class="beast-button hot" data-profile-action="save">Save Scope</button><button class="beast-button secondary" data-profile-action="effective">Resolve Effective</button><button class="beast-button secondary" data-profile-action="load-project">Load Project Profile</button><button class="beast-button hot" data-profile-action="save-project">Save Project Profile</button></div><pre data-profile-status>Profile subsystem ready.</pre>`;page.querySelector('.p8-settings-grid')?.append(panel);panel.addEventListener('click',async event=>{const action=event.target.closest('[data-profile-action]')?.dataset.profileAction;if(!action)return;const status=panel.querySelector('[data-profile-status]');const payload={...workspace(),scope:panel.querySelector('[data-profile-scope]').value,language:panel.querySelector('[data-profile-language]').value,target:panel.querySelector('[data-profile-target]').value};try{status.textContent='WORKING…';let result;if(action==='load')result=await desktop().settingsScope(payload);if(action==='save'){let values;try{values=JSON.parse(panel.querySelector('[data-profile-json]').value||'{}');}catch(_){throw new Error('Scoped settings must be valid JSON.');}result=await desktop().saveSettingsScope({...payload,values});}if(action==='effective')result=await desktop().effectiveSettings(payload);if(action==='load-project')result=await desktop().loadProjectProfile(payload);if(action==='save-project'){const state=window.BeastStore?.get?.()||{};result=await desktop().saveProjectProfile({...payload,name:`${payload.root.split('/').pop()||'BEAST'} profile`,keybindings:state.keybindings||{},layout:state.editorGroups||{},extensionSet:state.extensions?.enabled||[],uiDensity:state.settings?.density||'comfortable',modelRoute:state.models?.active||{},trustDefaults:state.trust||{}});}const value=result?.values||result?.profile?.settings||result?.profile||result||{};panel.querySelector('[data-profile-json]').value=JSON.stringify(value,null,2);status.textContent=`${action.toUpperCase()} · ${result?.digest||result?.receipt?.digest||'OK'}${result?.migrated?' · MIGRATED':''}`;}catch(error){status.textContent=`ERROR · ${String(error.message||error)}`;}});}
  const observer=new MutationObserver(mount);observer.observe(document.documentElement,{childList:true,subtree:true});document.addEventListener('beast:route-changed',mount);setInterval(mount,1200);mount();
})();
